def check_solution(n, a_list):
    """
    Checks if the set of pairwise sums of a_list matches {1, 2, ..., N}
    where N = n(n-1)/2.
    """
    if len(a_list) != n:
        return False

    # 1. Check distinctness of a_i (using a small epsilon for floating point comparison)
    epsilon = 1e-9
    unique_a = set()
    for a in a_list:
        is_unique = True
        for u in unique_a:
            if abs(a - u) < epsilon:
                is_unique = False
                break
        if is_unique:
            unique_a.add(a)

    if len(unique_a) != n:
        return False

    N = n * (n - 1) // 2
    target_sums = set(range(1, N + 1))

    # Calculate all pairwise sums
    sums = set()
    for i in range(n):
        for j in range(i + 1, n):
            s = a_list[i] + a_list[j]
            sums.add(s)

    # 2. Check if the set of sums equals the target set
    # We must handle floating point comparison carefully here too, 
    # but since the target is strictly integers, we check if the floats are close to integers.

    is_match = True
    if len(sums) != N:
        is_match = False
    else:
        for s in sums:
            # Check if s is close to an integer in the target range
            if not (1 <= s <= N) or abs(s - round(s)) > 1e-6:
                is_match = False
                break

        # Final check: ensure the set of rounded sums matches the target set
        rounded_sums = {round(s) for s in sums}
        if rounded_sums != target_sums:
            is_match = False

    return is_match

